    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        paths.sort();

        if paths.is_empty() {
            return ExitCode::Success;
        }

        let max_arg_length = max_command_line_length();

        // Length of everything except the placeholder-generated arguments (executable name and
        // any fixed arguments), used to determine how many paths can be batched together without
        // exceeding the maximum command line length supported by the shell/OS.
        let fixed_length: usize = std::iter::once(&self.args[0])
            .chain(self.args[1..].iter().filter(|arg| !arg.has_tokens()))
            .map(|arg| arg.generate("", None).len() + 1)
            .sum();

        let mut results = Vec::new();
        let mut chunk_start = 0;
        while chunk_start < paths.len() {
            let mut chunk_length = fixed_length;
            let mut chunk_end = chunk_start;

            while chunk_end < paths.len() {
                let arg_length = self.args[1..]
                    .iter()
                    .filter(|arg| arg.has_tokens())
                    .map(|arg| {
                        arg.generate(
                            strip_current_dir(&paths[chunk_end]),
                            self.path_separator.as_deref(),
                        )
                        .len()
                            + 1
                    })
                    .sum::<usize>();

                if chunk_end > chunk_start && chunk_length + arg_length > max_arg_length {
                    break;
                }

                chunk_length += arg_length;
                chunk_end += 1;
            }

            let mut cmd = Command::new(self.args[0].generate("", None));
            cmd.stdin(Stdio::inherit());
            cmd.stdout(Stdio::inherit());
            cmd.stderr(Stdio::inherit());

            for arg in &self.args[1..] {
                if arg.has_tokens() {
                    for path in &paths[chunk_start..chunk_end] {
                        cmd.arg(arg.generate(strip_current_dir(path), self.path_separator.as_deref()));
                    }
                } else {
                    cmd.arg(arg.generate("", None));
                }
            }

            results.push(execute_command(cmd, &Mutex::new(()), buffer_output));

            chunk_start = chunk_end;
        }

        merge_exitcodes(results)
    }
}

/// The maximum length (in bytes) of the argument list that we are willing to pass to a single
/// invocation of the executed command. This is used to split up very large batches of search
/// results (`--exec-batch`/`-X`) into multiple invocations, in order to avoid hitting the
/// operating system's limit on the total size of the command line (e.g. `argv`/`envp`), which
/// would otherwise cause an "Argument list too long" error.
fn max_command_line_length() -> usize {
    // Leave some headroom for the environment and other overhead that the OS also counts
    // against the limit.
    const HEADROOM: usize = 2048;

    #[cfg(unix)]
    let limit = {
        let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
        if arg_max > 0 {
            arg_max as usize
        } else {
            // Fall back to a conservative default (as used by e.g. GNU xargs) if the limit
            // could not be determined.
            128 * 1024
        }
    };

    #[cfg(not(unix))]
    let limit = {
        // Windows has a command line length limit of about 32768 characters.
        32 * 1024
    };

    limit.saturating_sub(HEADROOM).max(4096)
}

